CREATE TABLE IF NOT EXISTS einvoice_credentials (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, authority text NOT NULL CHECK (authority IN ('zatca','eta')), environment text NOT NULL CHECK (environment IN ('simulation','production')), csr text, private_key_enc text, csid_enc text, secret_enc text, org jsonb NOT NULL DEFAULT '{}', valid_from timestamptz, valid_to timestamptz, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS einvoice_credentials_tenant_authority_env_key ON einvoice_credentials(tenant_id, authority, environment);
CREATE TABLE IF NOT EXISTS einvoice_submissions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, invoice_id uuid NOT NULL REFERENCES sales_invoices(id) ON DELETE CASCADE, authority text NOT NULL CHECK (authority IN ('zatca','eta')), action text NOT NULL DEFAULT 'submit', environment text NOT NULL DEFAULT 'simulation', status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','cleared','reported','failed','not_implemented')), uuid uuid, hash text, previous_hash text, qr_payload text, request_payload jsonb NOT NULL DEFAULT '{}', response jsonb, error text, attempts text NOT NULL DEFAULT '0', submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS einvoice_submissions_invoice_idx ON einvoice_submissions(tenant_id, invoice_id);
CREATE INDEX IF NOT EXISTS einvoice_submissions_status_idx ON einvoice_submissions(tenant_id, status);
CREATE TABLE IF NOT EXISTS einvoice_chain (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, authority text NOT NULL, environment text NOT NULL, last_hash text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id, authority, environment));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['einvoice_credentials','einvoice_submissions','einvoice_chain'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('DROP POLICY IF EXISTS %I_tenant_isolation ON %I', t, t); EXECUTE format('CREATE POLICY %I_tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', t, t); END LOOP; END $$;
